import html
from pathlib import Path

ROOT = Path(__file__).resolve().parent
E = lambda value: html.escape(str(value), quote=True)

def t(zh, en, tag='span', cls=''):
    return f'<{tag} class="{cls}" data-zh="{E(zh)}" data-en="{E(en)}">{E(zh)}</{tag}>'

def a(url, zh, en, cls=''):
    extra = ' target="_blank" rel="noopener noreferrer"' if url.startswith('https://') else ''
    return f'<a href="{E(url)}" class="{cls}"{extra}>{t(zh,en)}</a>'

def cell(pair, secondary=None, cls=''):
    return '<td>'+t(*pair,'div',cls)+(t(*secondary,'div','secondary') if secondary else '')+'</td>'

