def table(headers,rows,cls='',caption=None):
    out='<div class="table-scroll" tabindex="0" role="region" aria-label="课程比较 / Course comparison"><table class="'+cls+'">'
    if caption:out+='<caption>'+t(*caption)+'</caption>'
    if cls=='comparison':out+='<colgroup><col class="col-course"><col class="col-topic"><col class="col-start"><col class="col-time"><col class="col-price"><col class="col-cert"><col class="col-age"></colgroup>'
    return out+'<thead><tr>'+''.join('<th scope="col">'+t(*h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'

